CREATE TABLE IF NOT EXISTS device_registry(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,device_ref TEXT NOT NULL,asset_ref TEXT NOT NULL,credential_fingerprint TEXT NOT NULL,schema_version TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'provisioned',created_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,device_ref),UNIQUE(tenant_id,credential_fingerprint));
CREATE TABLE IF NOT EXISTS governed_telemetry(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,device_id BIGINT NOT NULL REFERENCES device_registry(id),schema_version TEXT NOT NULL,metric TEXT NOT NULL,value DOUBLE PRECISION NOT NULL,unit TEXT NOT NULL,sequence BIGINT NOT NULL,recorded_at TIMESTAMPTZ NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,gap_count BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,device_id,sequence),UNIQUE(tenant_id,idempotency_key),CHECK(gap_count>=0));
CREATE TABLE IF NOT EXISTS governed_anomalies(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,device_id BIGINT NOT NULL REFERENCES device_registry(id),telemetry_id BIGINT REFERENCES governed_telemetry(id),detector_version TEXT NOT NULL,score DOUBLE PRECISION NOT NULL,evidence JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'detected',maintenance_reference TEXT,outcome_evidence JSONB,created_by BIGINT NOT NULL,approved_by BIGINT,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status IN ('detected','triaged','operator_review','maintenance_planned','resolved','verified','closed')));
CREATE TABLE IF NOT EXISTS iot_integration_runs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL,status TEXT NOT NULL,buffered_records INTEGER NOT NULL DEFAULT 0,error_code TEXT,error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status IN ('online','offline_buffering','replaying','failed')));
CREATE TABLE IF NOT EXISTS iot_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,actor_user_id BIGINT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,before_state JSONB,after_state JSONB,request_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
